window.GS_CATALOG={"daily":[{"slug":"serve-plus-one","title":"The Serve Writes the Next Question","line":"Read the reply your serve creates, then use the space.","sit":"Your wide serves have pulled this returner off the court twice. Watch both returns.","clips":["bh","fh","fhhi","fvhi","lowfv","ready","serveW"],"flavour":"tactics","cue":"Serve the question. Hit the space.","drill":{"name":"Serve and hit the space","how":"Serve 10 to each side. Before each serve, say where the return will go. The point only counts if your next shot goes into the space your serve opened."},"decisionCount":3},{"slug":"short-ball","title":"The Short Ball Is Not Permission","line":"Short isn't enough. Height, balance and their position earn the attack.","sit":"Their slice lands short and stays low. You come forward to it; they're still deep.","clips":["bh","bhlo","bv","fh","fhhi","fhlo","fvhi","ready"],"flavour":"tactics","cue":"Arrive balanced. Read the height. Earn the approach.","drill":{"name":"Earned or not","how":"Rally. On a short ball, call your contact height and whether you arrived balanced. Attack with margin when the space is earned. At low contact, lift with margin; follow only behind an approach that leaves you ready for the reply. Your partner checks your balance and recovery."},"decisionCount":3},{"slug":"the-line","title":"The Line Must Be Earned","line":"The open line is tempting. When is it actually on?","sit":"The line is open, but their low crosscourt pulls you wide, and you're late.","clips":["bh","bhlo","fh","fhhi","ready"],"flavour":"tactics","cue":"Heavy crosscourt until I earn the line.","drill":{"name":"Crosscourt until earned","how":"Rally crosscourt. You may change to the line only off a waist-high ball you're set for. A line attempt from a low ball, or one you're late for, loses the point, in or out."},"decisionCount":3},{"slug":"the-winner","title":"The Winner Can Be the Wrong Shot","line":"One winner proves little. Compare the margin in each choice.","sit":"Off a low, neutral ball, you go down the line and clip the paint. Winner.","clips":["bh","bhlo","fh","fhhi","fhlo","ready"],"flavour":"tactics","cue":"Would I choose it ten times?","drill":{"name":"The ten-ball test","how":"Pick a target and hit 10 balls at it from the same feed. Fewer than 7 in? It's too ambitious for a match. Move it a metre inside the line and go again."},"decisionCount":3},{"slug":"recovery","title":"The Centre Is Not the Plan","line":"Where you recover decides whether you reach their reply.","sit":"Your deep crosscourt pushes them outside the sideline. You finish balanced.","clips":["bh","bhlo","fh","fhhi","ready"],"flavour":"tactics","cue":"Recover to their angles.","drill":{"name":"Call the reply","how":"After each of your shots, call out where their reply is most likely to go, before they hit it, and recover toward that. Your partner counts your correct calls."},"decisionCount":3},{"slug":"open-court","title":"The Open Court Is Not Always Open","line":"Play the defender’s movement, not the empty space.","sit":"You have a comfortable short forehand. Watch where the defender is running before you choose.","clips":["bh","bhlo","fh","fhlo","ready"],"flavour":"tactics","cue":"Hit behind the run.","drill":{"name":"Behind the run","how":"Play out points. A point you win by hitting behind a running opponent counts double."},"decisionCount":3},{"slug":"forehand-bill","title":"Your Forehand Leaves a Bill","line":"A run-around forehand has to pay for the way back.","sit":"A deep ball to your backhand. They're balanced and could go either way.","clips":["bh","fh","fhhi","fhlo","ready"],"flavour":"tactics","cue":"Shot and recovery: one decision.","drill":{"name":"Pay the bill","how":"After each run-around forehand, recover while your ball travels. Your partner can reply to either side. Before their contact, balance where you can cover their likely angles; do not aim automatically for the centre mark. Play five points and notice which forehands leave you time to recover."},"decisionCount":3},{"slug":"the-lead","title":"The Lead That Makes You Smaller","line":"Ahead? Keep the depth that built the lead.","sit":"You lead 5–2. Your rally ball has started landing shorter.","clips":["bh","bhlo","fh","fhhi","ready"],"flavour":"tactics","cue":"Same depth, any score.","drill":{"name":"Start at 4-2","how":"Play sets starting at 4-2. The leader must land every rally ball past the service line. A short ball from the leader loses the point."},"decisionCount":3},{"slug":"split-step","title":"A Perfect Split Step Can Be Late","line":"Land for their hit, not before it.","sit":"You reach your spot. Watch the split step and your first move.","clips":["bhlo","fh","ready"],"flavour":"net","cue":"Watch their hit. Time your landing.","drill":{"name":"Time the landing","how":"Your partner feeds from both sides. Watch their strike, then land ready to push as the direction becomes readable. Notice any pause between landing and moving. Try twenty balls, then rally."},"decisionCount":3},{"slug":"approach-volley","title":"Your Approach Shapes Your First Volley","line":"A deep approach can earn a more manageable first volley.","sit":"You're balanced on a short forehand. Their recovery leaves the line open.","clips":["bh","bv","fh","lowfv","ready"],"flavour":"net","cue":"Deep, then follow it in.","drill":{"name":"Follow it in","how":"Approach deep and follow the line of your own ball. Your first volley must be played inside the service line. Your partner passes or lobs as they like."},"decisionCount":3},{"slug":"middle-return","title":"The Return That Shrinks Serve +1","line":"Depth through the middle can reduce the server’s angles.","sit":"A big first serve pulls you wide. The server stays back for their next ball.","clips":["bh","bhlo","fh","fhhi","ready","serveT","serveW"],"flavour":"tactics","cue":"Deep through the middle.","drill":{"name":"Middle and deep","how":"Returns score only if they land in the middle third of the court and past the service line. The server plays the point out."},"decisionCount":3},{"slug":"high-ball","title":"One High Ball. Two Opposite Answers.","line":"Find the contact, not the height.","sit":"A slower, high ball lands short. You're balanced, with time to move.","clips":["bh","bhlo","fh","fhChest","fhHigh","fhHigher","fhhi","ready"],"flavour":"tactics","cue":"Find the contact, not the height.","drill":{"name":"In or back","how":"Your partner feeds high balls, some short, some deep. Call \"in\" or \"back\" before the bounce, then play it. A wrong call loses the point."},"decisionCount":3},{"slug":"second-serve","title":"The Safe Second Serve Trap","line":"In is only the beginning.","sit":"Both second serves go in. Watch where the receiver meets each one.","clips":["bhChest","bhHigh","bhHigher","bhlo","fh","fhHigh","fhHigher","fhhi","ready","serveB","serveW"],"flavour":"tactics","cue":"In is only the beginning.","drill":{"name":"Second serves only","how":"Play games where every point starts on a second serve. The server wins a bonus point when the return is struck above the receiver's shoulder or off the body."},"decisionCount":3},{"slug":"contact-clue","title":"Two Misses. One Clue.","line":"Check the space at contact first.","sit":"Your forehand goes into the net. Watch it again, held at the moment you hit it.","clips":["fh","fhCramped","ready"],"flavour":"technique","cue":"Check the space first.","drill":{"name":"Space check","how":"Rally 20 forehands. After each, call \"crowded\", \"good\" or \"reaching\". Fix it with your feet, never the swing."},"decisionCount":3},{"slug":"running-around","title":"Running Around Is Not Hiding","line":"Earn the forehand. Cover its cost.","sit":"Your slice has bought time. Your forehand is your stronger shot.","clips":["bh","bhSlice","bhlo","fh","fhCramped","fhhi","fhlo","ready"],"flavour":"tactics","cue":"Earn the forehand.","drill":{"name":"Slice, then earn it","how":"Rally backhand to backhand. After one of your slices lands deep, you may run around the next ball for a forehand. Running around off a short slice loses the point."},"decisionCount":3},{"slug":"net-rusher","title":"Net Rusher: Feet or Over Them","line":"They come in. Where they stop decides: at their feet, or over them.","sit":"They approach and come in. They stop just inside the service line as you hit.","clips":["bh","bv","fh","fhhi","fvhi","lowfv","ready","sm"],"flavour":"opponents","cue":"Service line, feet. On the net, over.","drill":{"name":"Feet or over","how":"Your partner comes in and stops wherever they like. Around the service line, you must dip it at their feet. Close to the net, you must lob. The wrong choice loses the point, even if it wins."},"decisionCount":3},{"slug":"pass-where-they-arent","title":"Pass Where They Aren't","line":"At the net they cover one side. Pass the side they left.","sit":"They approach and close in, shading toward your down-the-line side.","clips":["bh","bv","fh","fvhi","ready"],"flavour":"net","cue":"Pass the side they left.","drill":{"name":"The side they left","how":"Your partner at the net leans to one side just before you hit. Pass the other side. A pass into the side they covered doesn't count, even if it wins."},"decisionCount":3},{"slug":"late-is-the-culprit","title":"Late Is the Culprit","line":"A repeated miss is a clue. Check the contact before changing the swing.","sit":"You aim crosscourt, but your forehand flies wide to the right. Watch it again, held at contact.","clips":["bh","fh","ready"],"flavour":"technique","cue":"Turn early. Meet it in front.","drill":{"name":"Turn on \"bounce\"","how":"Rally crosscourt and say \"bounce\" as the ball bounces on your side. Your shoulders must already be turned by the word. Count the forehands that leave straight, not wide."},"decisionCount":3},{"slug":"the-moonballer","title":"The Moonballer: Take Their Time","line":"They loop it high and deep. Take their time, then take the net.","sit":"Another high, heavy ball comes to your forehand. At the baseline it will kick above your shoulder.","clips":["bh","bhlo","fh","fhChest","fhHigher","fhhi","ready","sm"],"flavour":"opponents","cue":"Step in. Take their time.","drill":{"name":"Two steps in","how":"Your partner loops high balls. Start each one on the baseline and take it before it climbs above your shoulder. Backing up behind the baseline loses the point."},"decisionCount":3},{"slug":"the-pusher","title":"The Pusher: Change the Game","line":"They get everything back. Stop out-waiting them: change the game.","sit":"They're 2 m behind their baseline, looping everything back. This one lands short enough to step in on.","clips":["bhlo","bv","drop","fh","fvhi","lowfv","ready"],"flavour":"opponents","cue":"Deep? Drop it. Up? Come in.","drill":{"name":"The deep-or-up game","how":"Your partner loops from 2 m behind their baseline. Any ball that lands inside your service line, you must drop it. Driving it back loses the point. After 5 points they move up to the baseline, and now only a deep approach counts. First to 7."},"decisionCount":3},{"slug":"pulled-wide","title":"Pulled Wide? Buy Time First","line":"Off the court? Buy time first, unless you got there early.","sit":"Their angle pulls you off the court. You reach it low and late; they're in the middle.","clips":["bh","bhlo","fh","fhhi","fhlo","ready"],"flavour":"tactics","cue":"High and deep, then back.","drill":{"name":"Buy time","how":"Your partner pulls you wide with a feed. Your reply must clear the net by a racquet's length and land past the service line. Then play the point out."},"decisionCount":3},{"slug":"serve-away-from-the-lean","title":"Serve Away From the Lean","line":"The returner leans to cover one serve. Serve the side they left.","sit":"First serve from the deuce side. The returner has moved toward the T to protect their backhand.","clips":["bh","bhHigh","bhHigher","bhlo","fh","fhHigh","fhHigher","fhhi","fhlo","ready","serveB","serveT","serveW"],"flavour":"tactics","cue":"Read the lean. Serve away from it.","drill":{"name":"Serve away from the lean","how":"The returner takes a clear lean before each serve, wide or toward the T. Serve away from it. Score a point for every return they only block or don't reach; then let them lean late and see if you still read it."},"decisionCount":3},{"slug":"the-big-hitter","title":"The Big Hitter: Time for You, Not Them","line":"Their ball comes fast and heavy. Win back your time; keep it out of their zone.","sit":"They hit big. Their crosscourt forehand is coming into your backhand corner at 125 km/h.","clips":["bh","bhSlice","bhlo","fh","fhlo","ready"],"flavour":"opponents","cue":"Step back. Keep it out of their zone.","drill":{"name":"Out of the zone","how":"Your partner feeds hard, deep balls. Start one big step behind the baseline. Score a point for every reply that reaches them below the knee or above the shoulder, and lose one for every ball that sits at their waist."},"decisionCount":3},{"slug":"the-lefty","title":"The Lefty: Find Their Backhand","line":"Your usual patterns land on a lefty's forehand. Turn them round.","sit":"They're left-handed. You've run around your backhand to hit a forehand.","clips":["bh","bhHigh","bhSlice","bhlo","fh","fhChest","fhHigh","fhlo","ready","serveB","serveT","serveW"],"flavour":"opponents","cue":"Lefty? Flip your patterns.","drill":{"name":"Flip the pattern","how":"Rally with a left-hander, or a partner playing left-handed patterns. Score a point each time your ball lands on their backhand; lose one each time an inside-out forehand or a crosscourt backhand lands on their forehand."},"decisionCount":3},{"slug":"find-your-return-spot","title":"Find Your Return Spot","line":"Back for the big first serve. In for the kick second serve.","sit":"They hit a big first serve, around 185 km/h, down the T.","clips":["bh","fh","fhChest","fhHigh","ready","serveT","serveW"],"flavour":"tactics","cue":"Back for the big one. In for the kick.","drill":{"name":"Two spots","how":"Your partner alternates big first serves and kick second serves. Return the first from two steps back and the second from inside the baseline. Score a point for every return that lands past the service line."},"decisionCount":3},{"slug":"answer-the-drop","title":"Answer the Drop","line":"You got to their drop. Where they go decides your answer.","sit":"They drop-shot you and stay mid-court, where they hit it. You get there in time.","clips":["fh","fvhi","lowfv","ready"],"flavour":"net","cue":"Get there. Look up before choosing.","drill":{"name":"Drop and read","how":"Your partner varies the drop shot and their position. Arrive, look up and read your contact. Low or stretched? Give the reply height and margin. Early, balanced and higher, with them deep? Compare shorter placement into space with depth. Recover for the reply rather than judging only whether your first ball lands in."},"decisionCount":3},{"slug":"attack-the-backhand","title":"Attack the Backhand the Long Way","line":"Their backhand is weak and they know it. Move them off it first.","sit":"Their backhand is the weak side, and they've started leaning toward it before you hit.","clips":["bh","bhlo","bv","fh","fhhi","ready"],"flavour":"tactics","cue":"Other side first. Then the backhand.","drill":{"name":"The long way","how":"Rally crosscourt to your partner's forehand until they're pulled wide, then switch the next ball into the backhand corner. If it comes back short, approach down the line."},"decisionCount":3},{"slug":"down-the-line","title":"When to Go Down the Line","line":"The line is about where they are, not how brave you are.","sit":"Their crosscourt lands short. You step in, set, and they're still getting back to the middle.","clips":["bh","bhlo","fh","fhhi","fhlo","ready"],"flavour":"tactics","cue":"Where are they? Then where does it go.","drill":{"name":"Line or cross","how":"Rally crosscourt. On any short ball, glance at your partner: if they're still getting back to the middle, go down the line; if they've moved across early, go crosscourt behind them."},"decisionCount":3},{"slug":"rushed-out-wide","title":"Rushed Out Wide","line":"Pulled wide? Compare the margin and recovery time each reply gives you.","sit":"Their crosscourt pulls you off the court on your forehand side, and you only just get there.","clips":["bh","fh","fhhi","ready"],"flavour":"tactics","cue":"Out wide? Deep middle.","drill":{"name":"Wide and deep","how":"Your partner feeds wide to your forehand, then your backhand, some easy, some hard. Every one goes deep through the middle; count how many land past the service line."},"decisionCount":3},{"slug":"earned-attack","title":"Have You Earned the Attack?","line":"Read your arrival before taking the opening.","sit":"Their reply comes to your forehand. The far side is open.","clips":["fh","fhlo","ready"],"flavour":"tactics","cue":"See the space. Check your arrival.","drill":{"name":"Call the plan","how":"With a partner, vary the feed and your starting position. Before contact, call “pressure” or “buy time”. Afterwards, compare the call with your arrival, the ball and their position. Keep a useful cue; a won or lost point alone does not settle the decision."},"decisionCount":3},{"slug":"earned-defence","title":"Defence Can Change Before You Hit","line":"Your arrival changes the choices a wide ball offers.","sit":"Their ball takes you towards the sideline. Watch both players.","clips":["bhlo","fh","ready"],"flavour":"tactics","cue":"Need time? Buy it with height and depth.","drill":{"name":"Call the plan","how":"With a partner, vary the feed and your starting position. Before contact, call “pressure” or “buy time”. Afterwards, compare the call with your arrival, the ball and their position. Keep a useful cue; a won or lost point alone does not settle the decision."},"decisionCount":3},{"slug":"earned-net","title":"Have You Earned the Net?","line":"Arrive, read the ball, then decide whether to follow.","sit":"Their reply lands inside the service line. They remain deep.","clips":["bhlo","fh","ready"],"flavour":"tactics","cue":"Arrive first. Then decide whether to follow.","drill":{"name":"Call the plan","how":"With a partner, vary the feed and your starting position. Before contact, call “pressure” or “buy time”. Afterwards, compare the call with your arrival, the ball and their position. Keep a useful cue; a won or lost point alone does not settle the decision."},"decisionCount":3}],"predict":[{"slug":"predict-the-point","title":"Predict the Point: The Wide Serve Pattern","line":"Call the serve, the +1 and the finish. Then compare with a worked example.","sit":"30-30, deuce court. They crowd the middle to protect their backhand.","clips":["bh","bhChest","bhlo","fh","fhChest","fhhi","fhlo","ready","serveB","serveT","serveW"],"flavour":"predict","decisionCount":3},{"slug":"predict-second-serve","title":"Predict the Point: Break Point on a Second Serve","line":"Call the return, the approach and the volley. Then compare with a worked example.","sit":"15-40. A slow second serve sits up on your forehand. The server stays back.","clips":["bh","bhlo","bv","fh","fhhi","ready","serveT"],"flavour":"predict","decisionCount":3}],"play":[{"slug":"live-point-buy-time","title":"Buy Time. Use It.","line":"Your reply buys time. Your movement puts it to work.","sit":"","clips":["bh","fh","fhhi","fhlo","ready"],"flavour":"play","livePoint":true,"followup":"live-point-other-wing","decisionCount":4,"edition":"connected-four-v2","family":"recovery-time","learningSignals":["reply","recovery","direction","next-reply"],"cue":"Buy yourself time. Use it to recover.","drill":{"name":"Use the flight","how":"With a partner, start from a comfortable wide feed. Try a higher reply and a flatter one, then notice where you are when they hit. Judge your available time and position, not just the point result."}},{"slug":"live-point-other-wing","title":"Other Wing. Same Read?","line":"A new point on the other wing. Read it afresh.","sit":"","clips":["bhlo","fh","ready"],"flavour":"play","livePoint":true,"transferOf":"live-point-buy-time","decisionCount":2,"family":"recovery-time","learningSignals":["reply","recovery"],"cue":"Buy yourself time. Use it to recover.","drill":{"name":"Use the flight","how":"With a partner, start from a comfortable wide feed. Try a higher reply and a flatter one, then notice where you are when they hit. Judge your available time and position, not just the point result."}},{"slug":"live-point-make-room","title":"Make Room. Use It.","line":"Move early. Read the contact you create.","sit":"","clips":["fh","ready"],"flavour":"play","livePoint":true,"followup":"live-point-short-low","decisionCount":2,"edition":"six-play-v1","family":"contact-space","learningSignals":["preparation","contact-read"],"liveIntro":"Their ball is coming to your backhand side. You have time to move around it.","liveFeedback":{"summaries":{"10":"You made room. Check the ball and your balance before choosing.","11":"You made room and chose a reply that fits your preparation.","01":"You left less preparation time, then chose a reply with margin.","00":"The wait squeezed your preparation. The open side still carried risk."}},"returnPrompt":"The next point is shorter and lower. Does early arrival still earn a drive?","cue":"Make room early. Choose from the contact you have.","drill":{"name":"Prepare, then call it","how":"Ask a partner to vary the height of a comfortable short feed. Move early, adjust, then call “lift” or “drive” before contact. Judge the read and balance, not a winner."}},{"slug":"live-point-short-low","title":"Short Can Be Low.","line":"Early arrival helps. A low ball still needs lift.","sit":"","clips":["bhlo","fh","ready"],"flavour":"play","livePoint":true,"transferOf":"live-point-make-room","decisionCount":2,"edition":"six-play-v1","family":"contact-space","learningSignals":["preparation","contact-read"],"liveIntro":"A short ball is coming to your backhand. There is space ahead of you.","liveFeedback":{"summaries":{"10":"You moved early, but the low ball still needed clearance.","11":"You moved early and respected the low contact.","01":"You arrived hurried, then correctly gave the low ball clearance.","00":"The wait cost preparation time. The flat attempt then found the net."}},"cue":"Get there early. Low still needs lift.","drill":{"name":"Prepare, then call it","how":"Ask a partner to vary the height of a comfortable short feed. Move early, adjust, then call “lift” or “drive” before contact. Judge the read and balance, not a winner."}},{"slug":"live-point-serve-see","title":"Serve. Then See.","line":"Recover after the serve. Read what comes back.","sit":"","clips":["fh","fhhi","ready","serveW"],"flavour":"play","livePoint":true,"followup":"live-point-return-deep","decisionCount":2,"edition":"six-play-v1","family":"serve-readiness","learningSignals":["serve-recovery","return-read"],"liveIntro":"Your wide serve is on its way. The returner has not struck it yet.","liveFeedback":{"summaries":{"10":"You recovered. Let the actual return guide the next shot.","11":"You recovered, read the short return and chose from an organised contact.","01":"You corrected the early guess and chose a larger target.","00":"You guessed early, then pressed the angle while still adjusting."}},"returnPrompt":"The next return comes deeper. Read what it permits before using the same plan.","cue":"Recover after the serve. Read the return before attacking.","drill":{"name":"Prepare, then call it","how":"Have a partner alternate shorter and deeper returns. Recover after serving, then say “pressure” or “margin” from the return you see. Keep the rally going."}},{"slug":"live-point-return-deep","title":"The Return Pushes Back.","line":"A deeper return changes the plan.","sit":"","clips":["fh","fhhi","ready","serveW"],"flavour":"play","livePoint":true,"transferOf":"live-point-serve-see","decisionCount":2,"edition":"six-play-v1","family":"serve-readiness","learningSignals":["serve-recovery","return-read"],"liveIntro":"Your wide serve is travelling. The returner can still change the next ball.","liveFeedback":{"summaries":{"10":"You recovered, but forced the angle from a deeper contact.","11":"You recovered early and changed the plan for the deeper return.","01":"You corrected your position and adapted to the deeper return.","00":"The early guess cost preparation. The forced angle then went wide."}},"cue":"Read the return you get. Change the plan when it changes.","drill":{"name":"Prepare, then call it","how":"Have a partner alternate shorter and deeper returns. Recover after serving, then say “pressure” or “margin” from the return you see. Keep the rally going."}},{"slug":"live-point-return-pressure","title":"Return Under Pressure","line":"Read the serve’s pace, then read the next ball afresh.","sit":"","clips":["bh","bhlo","fh","ready","serveT"],"flavour":"play","livePoint":true,"followup":"live-point-return-time","decisionCount":2,"edition":"ten-live-v1","family":"return-pressure","learningSignals":["serve-pace","reply-margin"],"liveIntro":"A fast serve is coming into your backhand. Your preparation window is small.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"returnPrompt":"A different ball changes the decision. Try the paired point.","cue":"Read the pace. Give your return room, then recover.","drill":{"name":"Two-ball read","how":"Alternate faster and slower serves to the same wing. Call “compact” or “time” before the return, then play one more ball."}},{"slug":"live-point-return-time","title":"Return With Time","line":"Pressure comes from the serve you receive, not its first-or-second label.","sit":"","clips":["bh","bhlo","fh","fhhi","ready","serveT"],"flavour":"play","livePoint":true,"transferOf":"live-point-return-pressure","decisionCount":2,"edition":"ten-live-v1","family":"return-pressure","learningSignals":["return-opportunity","next-contact"],"liveIntro":"This serve arrives more slowly. You can meet it inside the baseline with space to swing.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"cue":"Use the time. Apply pressure, then read what comes back.","drill":{"name":"Two-ball read","how":"Have a partner vary serve pace without announcing it. Return to a large target and call the depth of the next ball before playing it."}},{"slug":"live-point-line-tempting","title":"The Line Is Tempting","line":"An empty corner is only an opportunity if your contact supports the shot.","sit":"","clips":["bh","bhlo","fh","ready"],"flavour":"play","livePoint":true,"followup":"live-point-line-opens","decisionCount":2,"edition":"ten-live-v1","family":"direction-change","learningSignals":["direction-margin","recovery-read"],"liveIntro":"You are pulled wide and behind the baseline on your backhand. The opposite sideline looks inviting.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"returnPrompt":"A different ball changes the decision. Try the paired point.","cue":"Balance before direction. Give yourself room to recover.","drill":{"name":"Two-ball read","how":"Alternate a wide deep feed and a shorter central feed. Call “hold” or “change” before contact; recover and play the next ball."}},{"slug":"live-point-line-opens","title":"Now the Line Opens","line":"The line changes with your contact. Read what makes it available.","sit":"","clips":["bh","bhlo","fh","ready"],"flavour":"play","livePoint":true,"transferOf":"live-point-line-tempting","decisionCount":2,"edition":"ten-live-v1","family":"direction-change","learningSignals":["direction-opportunity","follow-up-read"],"liveIntro":"This ball is shorter. You have time to set on the backhand, and they are recovering toward the crosscourt side.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"cue":"Use the opening you earn. Cover the reply it creates.","drill":{"name":"Two-ball read","how":"Alternate a deep wide backhand feed and a shorter one. Recover toward the crosscourt side as feeder. Let the receiver call the opening, then play your actual reply."}},{"slug":"live-point-volley-build","title":"First Volley: Build the Point","line":"A low first volley builds the point. Depth can earn the next ball.","sit":"","clips":["bh","bv","fh","lowfv","ready"],"flavour":"play","livePoint":true,"followup":"live-point-volley-opening","decisionCount":2,"edition":"ten-live-v1","family":"first-volley","learningSignals":["volley-height","second-volley"],"liveIntro":"Your approach brings you in. Their passing shot dips below net height on your forehand side.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"returnPrompt":"A different ball changes the decision. Try the paired point.","cue":"Low volley, compact action. Build the point, then stay ready.","drill":{"name":"Two-ball read","how":"Approach a deep feed. Have the passer alternate low forehand and backhand passes. Play two volleys, valuing balance and depth before a finish."}},{"slug":"live-point-volley-opening","title":"First Volley: Use the Opening","line":"A higher volley offers options. Read the next pass before choosing again.","sit":"","clips":["bh","bv","fh","fvhi","ready"],"flavour":"play","livePoint":true,"transferOf":"live-point-volley-build","decisionCount":2,"edition":"ten-live-v1","family":"first-volley","learningSignals":["volley-opportunity","next-volley-read"],"liveIntro":"Your approach moves them wide. This backhand volley is above the net, with the opposite side open.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"cue":"Use the height and space. Place it, then stay ready.","drill":{"name":"Two-ball read","how":"Have a partner feed one low volley and one above the net, while changing sides. Call “build” or “place” from the contact and court, then play a second volley."}},{"slug":"live-point-pass-two","title":"Pass in Two","line":"Build the pass in two balls. Read the volley before choosing again.","sit":"","clips":["bhlo","fh","fvhi","lowfv","ready"],"flavour":"play","livePoint":true,"followup":"live-point-over-head","decisionCount":2,"edition":"ten-live-v1","family":"passing-read","learningSignals":["first-pass-height","volley-read"],"liveIntro":"They are coming in and covering the obvious passing lane. Your contact is low behind the baseline.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"returnPrompt":"A different ball changes the decision. Try the paired point.","cue":"Make the first volley difficult. Read it before you pass.","drill":{"name":"Two-ball read","how":"Start with a partner approaching. Play a low first pass, then call the actual volley’s depth before selecting the second shot. Change the volley direction each time."}},{"slug":"live-point-over-head","title":"Over Their Head","line":"Their net position changes the space. Recover while the lob travels.","sit":"","clips":["bhlo","fh","fvhi","ready"],"flavour":"play","livePoint":true,"transferOf":"live-point-pass-two","decisionCount":2,"edition":"ten-live-v1","family":"passing-read","learningSignals":["net-distance","lob-follow-up"],"liveIntro":"They have closed much nearer the net and cover the passing angles. You have room to lift the ball.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"cue":"Read how close they stand. Use the space above them.","drill":{"name":"Two-ball read","how":"Have a partner vary how close they stand to the net. Choose feet or lob from the position, then continue with whichever reply they reach."}},{"slug":"live-point-reach-drop","title":"Reach the Drop","line":"Reaching a drop shot is only the first job. Your balance shapes the reply.","sit":"","clips":["bh","bv","drop","fh","ready"],"flavour":"play","livePoint":true,"followup":"live-point-arrive-options","decisionCount":2,"edition":"ten-live-v1","family":"drop-arrival","learningSignals":["drop-pickup","balance-recovery"],"liveIntro":"You read the drop late from behind the baseline. You reach it low, still moving forward.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"returnPrompt":"A different ball changes the decision. Try the paired point.","cue":"Reach the ball, then find balance. Keep the next shot playable.","drill":{"name":"Two-ball read","how":"Begin deep. Have a partner disguise an occasional drop shot, then play a pass after your pickup. Judge the pickup height and how quickly you regain balance."}},{"slug":"live-point-arrive-options","title":"Arrive With Options","line":"Earlier arrival creates options. Placement still depends on their position.","sit":"","clips":["bv","drop","fh","fvhi","ready"],"flavour":"play","livePoint":true,"transferOf":"live-point-reach-drop","decisionCount":2,"edition":"ten-live-v1","family":"drop-arrival","learningSignals":["early-drop-read","placement-follow-up"],"liveIntro":"You spot the drop early. You arrive higher and more balanced, while they remain deep near the middle.","liveFeedback":{"summaries":{"10":"The first choice fitted. The next ball needed a fresh decision.","11":"Both choices fitted the contact and court you had. Keep reading as the point changes.","01":"You adapted on the second ball. Compare what the first choice cost.","00":"Compare the first choice, then read the next contact again. A landing alone does not prove a sound decision."}},"cue":"Early arrival creates options. Place the ball, then stay ready.","drill":{"name":"Two-ball read","how":"Alternate a disguised drop with an obvious one. Let the receiver call “reach” or “options”, place the pickup, then play the real passing shot and next volley."}},{"slug":"doubles-cross-cover","title":"They Cross. You Cover.","line":"Your partner crosses. Cover the space they leave.","sit":"","clips":["bh","bv","fh","fvhi","ready","serveT"],"flavour":"doubles","livePoint":true,"doubles":true,"pairPlan":"If you cross for the return, I cover behind you. Let’s agree the serve target first.","followup":"doubles-hold-cover","decisionCount":2,"edition":"doubles-v1","family":"doubles-serve","learningSignals":["pair-coverage","next-contact"],"liveIntro":"You serve. Your partner crosses for the return. For a moment, their old side looks painfully open.","liveFeedback":{"summaries":{"10":"The pair’s first move fitted. The next contact still needed margin.","11":"You read the pair’s coverage and gave the next ball room.","01":"Your next shot had margin. Review the first coverage call together.","00":"Review the first call, then choose a target that fits the next contact."}},"returnPrompt":"Same partnership. Read what has changed.","cue":"Partner crosses. Cover the space they leave.","drill":{"name":"Rehearse as a pair","how":"Agree a serve target and a crossing signal. Play the return and two more balls. After each point, both name the space they were covering."}},{"slug":"doubles-return-space","title":"Return Past the Net Player","line":"Read the net player and the return lane.","sit":"","clips":["bv","fh","ready","serveT"],"flavour":"doubles","livePoint":true,"doubles":true,"pairPlan":"Let’s read the net player before returning. Use the crosscourt lane when it is available, then get ready together.","followup":"doubles-return-line","decisionCount":2,"edition":"doubles-v1","family":"doubles-return","learningSignals":["pair-coverage","next-contact"],"liveIntro":"The net player looks ready to pounce. You still have a crosscourt lane to the server. Don’t let their presence choose your return.","liveFeedback":{"summaries":{"10":"The pair’s first move fitted. The next contact still needed margin.","11":"You read the pair’s coverage and gave the next ball room.","01":"Your next shot had margin. Review the first coverage call together.","00":"Review the first call, then choose a target that fits the next contact."}},"returnPrompt":"Same partnership. Read what has changed.","cue":"Read the net player. Return through the available space.","drill":{"name":"Rehearse as a pair","how":"Serve ten practice points. The net player sometimes holds and sometimes moves across. Returners name the lane they saw; both partners recover for the reply."}},{"slug":"doubles-lob-switch","title":"Who Takes the Deep Lob?","line":"Call early. Retrieve and cover as a pair.","sit":"","clips":["bh","fh","lowfv","ready"],"flavour":"doubles","livePoint":true,"doubles":true,"pairPlan":"For a lob beyond the net player, call early: “Yours, switching.” The retriever calls “Mine”; the other player covers and retreats.","followup":"doubles-lob-overhead","decisionCount":2,"edition":"doubles-v1","family":"doubles-lob","learningSignals":["pair-coverage","next-contact"],"liveIntro":"A deep lob goes over you. Your partner is already deeper. Both of you chasing it would leave nobody organising the next ball.","liveFeedback":{"summaries":{"10":"The pair’s first move fitted. The next contact still needed margin.","11":"You read the pair’s coverage and gave the next ball room.","01":"Your next shot had margin. Review the first coverage call together.","00":"Review the first call, then choose a target that fits the next contact."}},"returnPrompt":"Same partnership. Read what has changed.","cue":"Call early. Cover while your partner retrieves.","drill":{"name":"Rehearse as a pair","how":"Start one up, one back. Feed a deep lob. Require an early ownership call, a switch and a recovery shot, then play out the next two balls."}},{"slug":"doubles-hold-cover","title":"They Hold. So Do You.","line":"A partner who holds changes your coverage job.","sit":"","clips":["fh","ready","serveT"],"flavour":"doubles","livePoint":true,"doubles":true,"pairPlan":"If you hold at the net, I keep my half. We switch when the movement calls for it, not automatically.","transferOf":"doubles-cross-cover","decisionCount":2,"edition":"doubles-v1","family":"doubles-serve","learningSignals":["pair-coverage","next-contact"],"liveIntro":"Same serving pair. This time your partner holds position and the return comes to your half. The crossing plan no longer fits.","liveFeedback":{"summaries":{"10":"The pair’s first move fitted. The next contact still needed margin.","11":"You read the pair’s coverage and gave the next ball room.","01":"Your next shot had margin. Review the first coverage call together.","00":"Review the first call, then choose a target that fits the next contact."}},"returnPrompt":"Same partnership. Read what has changed.","cue":"Partner holds. Keep covering your half.","drill":{"name":"Rehearse as a pair","how":"Alternate agreed cross and hold signals before serving. Play the return. The server must cover the appropriate half without guessing from the previous point."}},{"slug":"doubles-return-line","title":"Now the Line Is Open","line":"Their early crossing move opens a different lane.","sit":"","clips":["bh","fh","fvhi","ready","serveT"],"flavour":"doubles","livePoint":true,"doubles":true,"pairPlan":"If their net player crosses early and the serve gives us time, use the vacated line with margin. Keep covering the next ball.","transferOf":"doubles-return-space","decisionCount":2,"edition":"doubles-v1","family":"doubles-return","learningSignals":["pair-coverage","next-contact"],"liveIntro":"The net player moves early toward the middle. This serve gives you enough time to see the lane they have left.","liveFeedback":{"summaries":{"10":"The pair’s first move fitted. The next contact still needed margin.","11":"You read the pair’s coverage and gave the next ball room.","01":"Your next shot had margin. Review the first coverage call together.","00":"Review the first call, then choose a target that fits the next contact."}},"returnPrompt":"Same partnership. Read what has changed.","cue":"When they leave the line, read the opening.","drill":{"name":"Rehearse as a pair","how":"Repeat the return drill with an occasional early crossing move. Reward recognising the changed lane and recovering; do not award extra points for outright winners."}},{"slug":"doubles-lob-overhead","title":"This Lob Is Yours","line":"A shorter lob changes who should take it.","sit":"","clips":["bh","bv","fh","lowfv","ready","sm"],"flavour":"doubles","livePoint":true,"doubles":true,"pairPlan":"Take a reachable overhead with an early “Mine.” The partner covers behind. If it carries beyond reach, call the switch early.","transferOf":"doubles-lob-switch","decisionCount":2,"edition":"doubles-v1","family":"doubles-lob","learningSignals":["pair-coverage","next-contact"],"liveIntro":"This lob is shorter. You have time to turn and get under it. Calling your partner through would give away that comfortable overhead.","liveFeedback":{"summaries":{"10":"The pair’s first move fitted. The next contact still needed margin.","11":"You read the pair’s coverage and gave the next ball room.","01":"Your next shot had margin. Review the first coverage call together.","00":"Review the first call, then choose a target that fits the next contact."}},"returnPrompt":"Same partnership. Read what has changed.","cue":"Reachable overhead? Call it. Your partner covers.","drill":{"name":"Rehearse as a pair","how":"Mix short and deep lobs without announcing them. Call ownership early. After a reachable overhead, insist on playing the next defensive reply."}},{"slug":"saturday-point-1","title":"Saturday Point #1","line":"One point, built from five of your lessons. Read each contact and choose the margin it offers.","sit":"30-30, deuce court. The returner stands close to the middle to protect their backhand.","clips":["bh","bhlo","fh","fhChest","fhhi","fhlo","ready","serveT","serveW"],"flavour":"play","decisionCount":5,"uses":["serve-plus-one","short-ball","open-court","the-line","the-winner"]},{"slug":"saturday-point-2","title":"Saturday Point #2","line":"A return game at 5-2, built from five more of your lessons. Read each contact and choose the margin it offers.","sit":"You lead 5–2. Their serve: a big first serve, wide to your forehand.","clips":["bh","bhlo","bv","fh","fhhi","ready","serveW"],"flavour":"play","decisionCount":5,"uses":["middle-return","the-lead","recovery","approach-volley","split-step"]},{"slug":"saturday-point-3","title":"Saturday Point #3","line":"Your serve at 30-40, built from five more of your lessons. Read each contact and choose the margin it offers.","sit":"30–40. You missed your first serve.","clips":["bh","bhChest","bhHigher","bhSlice","bhlo","fh","fhCramped","fhHigher","fhhi","fvhi","lowfv","ready","serveB"],"flavour":"play","decisionCount":5,"uses":["second-serve","high-ball","running-around","contact-clue","net-rusher"]},{"slug":"saturday-point-4","title":"Saturday Point #4: The Pusher","line":"One point against a pusher, built from five more of your lessons. Read each contact and choose the margin it offers.","sit":"30–15. The returner has shaded wide to cover your wide serve.","clips":["bh","bhHigher","drop","fh","fhHigher","fhhi","fhlo","ready","serveT","serveW"],"flavour":"play","decisionCount":5,"uses":["serve-away-from-the-lean","forehand-bill","pulled-wide","down-the-line","the-pusher"]},{"slug":"saturday-point-5","title":"Saturday Point #5: The Big Hitter","line":"Break point against a big hitter, built from five more of your lessons. Read each contact and choose the margin it offers.","sit":"30–40, break point. Their big first serve is coming down the T.","clips":["bh","bhlo","fh","fhChest","fhHigher","fhhi","fhlo","fvhi","ready","serveT"],"flavour":"play","decisionCount":5,"uses":["find-your-return-spot","the-big-hitter","attack-the-backhand","the-moonballer","answer-the-drop"]},{"slug":"midweek-point-1","title":"Midweek Point #1","line":"Three shots from three of your lessons. A quick top-up between Saturdays.","sit":"15–30. Their second serve is a high, heavy kick.","clips":["bh","bhlo","fh","fhChest","fhhi","ready","serveT"],"flavour":"play","decisionCount":3,"uses":["find-your-return-spot","rushed-out-wide","down-the-line"]},{"slug":"play-the-point","title":"Play the Point","line":"Three shots, your calls. Each choice decides what happens next.","sit":"","clips":["bh","bhlo","fh","fhChest","fhhi","ready","serveT","serveW"],"flavour":"play"}],"flavours":[{"key":"doubles","name":"Doubles","lessons":["doubles-cross-cover","doubles-return-space","doubles-lob-switch","doubles-hold-cover","doubles-return-line","doubles-lob-overhead"]},{"key":"tactics","name":"Court tactics","lessons":["serve-plus-one","short-ball","the-line","the-winner","recovery","open-court","forehand-bill","the-lead","middle-return","high-ball","second-serve","running-around","pulled-wide","serve-away-from-the-lean","find-your-return-spot","attack-the-backhand","down-the-line","rushed-out-wide","earned-attack","earned-defence","earned-net"]},{"key":"opponents","name":"Opponents","lessons":["the-moonballer","the-pusher","net-rusher","the-big-hitter","the-lefty"]},{"key":"net","name":"Net play","lessons":["approach-volley","pass-where-they-arent","split-step","answer-the-drop"]},{"key":"technique","name":"Technique","lessons":["late-is-the-culprit","contact-clue"]},{"key":"predict","name":"Predict the Point","lessons":["predict-the-point","predict-second-serve"]},{"key":"play","name":"Play the Point","lessons":["live-point-buy-time","live-point-other-wing","live-point-make-room","live-point-short-low","live-point-serve-see","live-point-return-deep","live-point-return-pressure","live-point-return-time","live-point-line-tempting","live-point-line-opens","live-point-volley-build","live-point-volley-opening","live-point-pass-two","live-point-over-head","live-point-reach-drop","live-point-arrive-options","saturday-point-1","saturday-point-2","saturday-point-3","saturday-point-4","saturday-point-5","midweek-point-1","play-the-point"]}],"dailyPlan":{"edition":"daily-2026-11","startDate":"2026-11-09","rotation":["serve-plus-one","short-ball","the-line","the-winner","recovery","open-court","forehand-bill","the-lead","split-step","approach-volley","middle-return","high-ball","second-serve","contact-clue","running-around","net-rusher","pass-where-they-arent","late-is-the-culprit","the-moonballer","the-pusher","pulled-wide","serve-away-from-the-lean","the-big-hitter","the-lefty","find-your-return-spot","answer-the-drop","attack-the-backhand","down-the-line","rushed-out-wide","earned-attack","earned-defence","earned-net"],"related":{"serve-plus-one":{"slug":"live-point-serve-see","bridge":"Use the serve to set up the next ball, then read the return you actually get."},"short-ball":{"slug":"live-point-make-room","bridge":"Read the ball and create space before deciding how to attack."},"the-line":{"slug":"live-point-line-tempting","bridge":"Test whether the line is available while the point keeps moving."},"recovery":{"slug":"live-point-buy-time","bridge":"Choose a reply, then decide when to recover."},"open-court":{"slug":"live-point-line-tempting","bridge":"Check the opening and your own position before changing direction."},"approach-volley":{"slug":"live-point-volley-build","bridge":"Choose the first volley and prepare for the next reply."},"middle-return":{"slug":"live-point-return-pressure","bridge":"Choose a return that gives you a workable next ball."},"net-rusher":{"slug":"live-point-pass-two","bridge":"Use the first pass to shape the next opening."},"pass-where-they-arent":{"slug":"live-point-pass-two","bridge":"Read the net player, then make the next passing decision."},"pulled-wide":{"slug":"live-point-buy-time","bridge":"Buy time with the reply and use it to recover."},"find-your-return-spot":{"slug":"live-point-return-pressure","bridge":"Read the serve and make the return decision under pressure."},"answer-the-drop":{"slug":"live-point-reach-drop","bridge":"Read how you arrive before choosing your reply."},"down-the-line":{"slug":"live-point-line-tempting","bridge":"Make the direction decision in a changing point."},"rushed-out-wide":{"slug":"live-point-buy-time","bridge":"Read the reply and recovery as two connected decisions."},"earned-attack":{"slug":"live-point-make-room","bridge":"See how your preparation changes the attacking options."},"earned-defence":{"slug":"live-point-buy-time","bridge":"Choose enough time to get back into the point."},"earned-net":{"slug":"live-point-volley-build","bridge":"Build from the first volley instead of rushing the finish."},"predict-the-point":{"slug":"live-point-serve-see","bridge":"Anticipate the return, then respond to the ball you actually receive."},"predict-second-serve":{"slug":"live-point-return-pressure","bridge":"Take the return read into a point with consequences."}},"home":{"serve-plus-one":{"title":"Your wide serve worked. Now what?","setup":"Watch two returns. Choose your next move."},"short-ball":{"title":"A short ball. An easy winner?","setup":"Their slice stays low. Decide how much to attack."},"the-line":{"title":"The line is open. Are you ready?","setup":"You are wide and late. Make your call."},"the-winner":{"title":"A winner. But the right choice?","setup":"You clip the line. Decide what that really tells you."},"recovery":{"title":"Your shot is good. Where next?","setup":"You have pulled them wide. Find your recovery spot."},"open-court":{"title":"Open court. Or behind them?","setup":"Watch the defender move before choosing your target."},"forehand-bill":{"title":"Run around—or hold your ground?","setup":"A deep ball to your backhand. Weigh the forehand against the recovery."},"the-lead":{"title":"5–2 up. Why change now?","setup":"Your rally ball is getting shorter. Choose your next intention."},"split-step":{"title":"Ready to move. A moment too late?","setup":"Watch the split step and the first move."},"approach-volley":{"title":"Which approach earns the volley?","setup":"A short forehand. Choose how to come forward."},"middle-return":{"title":"Big serve. Where do you return?","setup":"You are pulled wide. The server is waiting for your reply."},"high-ball":{"title":"Same high ball. Same answer?","setup":"Read your time and contact before choosing where to meet it."},"second-serve":{"title":"Both serves land in. Equally safe?","setup":"Watch where the returner meets each second serve."},"contact-clue":{"title":"Into the net. What would you change?","setup":"Look closely at the moment the ball meets your racket."},"running-around":{"title":"Time for your forehand?","setup":"Your slice has bought time. Decide how to use it."},"net-rusher":{"title":"At their feet—or over their head?","setup":"They come to net. Read where they stop."},"pass-where-they-arent":{"title":"They close the net. Where is the gap?","setup":"Watch which side they cover before choosing your pass."},"late-is-the-culprit":{"title":"Wide again. What is the clue?","setup":"You aimed crosscourt. Freeze the contact and take a closer look."},"the-moonballer":{"title":"Another high ball. Your move?","setup":"It will bounce above your shoulder. Choose where to take it."},"the-pusher":{"title":"They get everything back. Now what?","setup":"A shorter ball gives you a chance to change the pattern."},"pulled-wide":{"title":"Off the court. Still in the point.","setup":"You reach it low and late. Choose your reply."},"serve-away-from-the-lean":{"title":"They are leaning. Where do you serve?","setup":"Read the returner before choosing your first-serve target."},"the-big-hitter":{"title":"Their pace. Your starting position.","setup":"A big forehand is coming. Decide where to wait."},"the-lefty":{"title":"A lefty. Does your pattern still work?","setup":"You have run around your backhand. Choose your forehand target."},"find-your-return-spot":{"title":"Big serve. Where do you stand?","setup":"Watch the serve, then choose your starting position."},"answer-the-drop":{"title":"You reach the drop. What next?","setup":"You arrive in time. Read where your opponent has stopped."},"attack-the-backhand":{"title":"They know you want their backhand.","setup":"They are leaning to protect it. Choose where to go first."},"down-the-line":{"title":"Is this your ball down the line?","setup":"You step into a shorter ball. Read their recovery."},"rushed-out-wide":{"title":"Just reached it. What do you play?","setup":"You are stretched wide. Compare your options."},"earned-attack":{"title":"Open space. Have you earned it?","setup":"Read your arrival before deciding to attack."},"earned-defence":{"title":"Pulled wide. Is defence the only choice?","setup":"Watch your arrival and your opponent before choosing."},"earned-net":{"title":"A short reply. Should you follow?","setup":"Read your contact before committing to the net."}}}};
